# Hypothesis: none -- instruction pool + checkers, tested on toy strings.
def words(s): return re.findall(r"[A-Za-z0-9]+(?:'[A-Za-z]+)?", s)
def sentences(s):
    parts = re.split(r'(?<=[.!?])\s+', s.strip())
    return [p for p in parts if re.search(r'[A-Za-z0-9]', p)]
def strip_json_fence(s):
    s = s.strip()
    m = re.match(r'^`{3}(?:json|JSON)?\s*\n?(.*?)\n?`{3}$', s, re.S)
    return m.group(1) if m else s

KW_POOL = ['window','silver','harvest','journey','lantern','garden','thunder','balance','whisper','compass','meadow','engine',
           'feather','mirror','orchard','candle','bridge','harbor','puzzle','velvet','anchor','canyon','ribbon','marble']
WORD_POOL = ['light','home','together','bright','again','dream','road','heart','time','song']
END_PHRASES = ['That is all for today.', 'Thank you for reading.', 'Until we meet again.', 'And that is the whole story.', 'Let me know what you think.']
START_WORDS = ['Indeed','Today','Listen','Once','Well']

def make_instruction(kind, task, r):
    if kind=='words_min':
        n = r.choice([150,200,250,300,400,500]); return (f"Your response should contain at least {n} words.", lambda a,n=n: len(words(a))>=n)
    if kind=='words_max':
        n = r.choice([60,80,100,120,150,200]); return (f"Your response should contain at most {n} words.", lambda a,n=n: 0<len(words(a))<=n)
    if kind=='sent_min':
        n = r.choice([8,10,12,15,20]); return (f"Your response should contain at least {n} sentences.", lambda a,n=n: len(sentences(a))>=n)
    if kind=='sent_max':
        n = r.choice([3,4,5,6,8]); return (f"Your answer must contain at most {n} sentences.", lambda a,n=n: 0<len(sentences(a))<=n)
    if kind=='paragraphs':
        n = r.choice([2,3,4,5]); return (f"There should be exactly {n} paragraphs. Paragraphs are separated from each other by the markdown divider: ***",
            lambda a,n=n: len([p for p in re.split(r'\n\s*\*\*\*\s*\n', a.strip()) if p.strip()])==n and a.count('***')==n-1)
    if kind=='keywords':
        ks = r.sample(KW_POOL, 2); return (f"Include the keywords '{ks[0]}' and '{ks[1]}' in your response.",
            lambda a,ks=ks: all(re.search(r'\b'+k+r'\b', a, re.I) for k in ks))
    if kind=='word_freq':
        w = r.choice(WORD_POOL); n = r.choice([3,4,5,6]); return (f"Use the word '{w}' at least {n} times.",
            lambda a,w=w,n=n: len(re.findall(r'\b'+w+r'\b', a, re.I))>=n)
    if kind=='end_phrase':
        p = r.choice(END_PHRASES); return (f"Finish your response with this exact phrase: '{p}'. No other words should follow it.", lambda a,p=p: a.strip().endswith(p))
    if kind=='postscript':
        return ("At the end of your response, please explicitly add a postscript starting with P.S.", lambda a: re.search(r'(^|\n)\s*P\.\s?S\.', a, re.I) is not None)
    if kind=='lowercase':
        return ("Your entire response should be in English, and in all lowercase letters. No capital letters are allowed.", lambda a: a==a.lower() and re.search('[a-z]',a) is not None)
    if kind=='uppercase':
        return ("Your entire response should be in English and in all capital letters.", lambda a: a==a.upper() and re.search('[A-Z]',a) is not None)
    if kind=='no_commas':
        return ("In your entire response, refrain from the use of any commas.", lambda a: ',' not in a and len(a.strip())>0)
    if kind=='quotation':
        return ("Wrap your entire response with double quotation marks.", lambda a: len(a.strip())>1 and a.strip()[0]=='"' and a.strip()[-1]=='"')
    if kind=='json':
        def cj(a):
            try: json.loads(strip_json_fence(a)); return True
            except Exception: return False
        return ("Entire output should be wrapped in JSON format. You can use markdown ticks such as ```.".replace('```', '`'*3), cj)
    if kind=='title':
        return ("Your answer must contain a title, wrapped in double angular brackets, such as <<my title>>.", lambda a: re.search(r'<<[^\n<>]+>>', a) is not None)
    if kind=='highlights':
        n = r.choice([2,3,4]); return (f"Highlight at least {n} sections in your answer with markdown, i.e. *highlighted section*.", lambda a,n=n: len(re.findall(r'\*[^\n\*]+\*', a))>=n)
    if kind=='bullets':
        n = r.choice([3,4,5]); return (f"Your answer must contain exactly {n} bullet points. Use the markdown bullet points such as:\n* This is point 1.",
            lambda a,n=n: len(re.findall(r'^\s*[\*\-] ', a, re.M))==n)
    if kind=='repeat':
        return ("First repeat the request word for word without change, then give your answer (1. do not say any words or characters before repeating the request; 2. the request you need to repeat does not include this sentence)",
            lambda a,t=task: a.strip().lower().startswith(t.strip().lower()))
    if kind=='two_resp':
        def c2(a):
            parts = a.split('******')
            return len(parts)==2 and all(p.strip() for p in parts) and parts[0].strip()!=parts[1].strip()
        return ("Give two different responses. Responses and only responses should be separated by 6 asterisk symbols: ******.", c2)
    if kind=='placeholders':
        n = r.choice([2,3,4]); return (f"The response must contain at least {n} placeholders represented by square brackets, such as [address].", lambda a,n=n: len(re.findall(r'\[[^\[\]\n]+\]', a))>=n)
    if kind=='sections':
        n = r.choice([2,3,4]); return (f"Your response must have {n} sections. Mark the beginning of each section with SECTION X, such as: SECTION 1",
            lambda a,n=n: len(re.findall(r'(?:^|\n)\s*\**\s*SECTION\s+\d+', a))==n)
    if kind=='start_word':
        w = r.choice(START_WORDS); return (f"Start your response with the word '{w}'.", lambda a,w=w: re.match(r'^\W*'+w+r'\b', a.strip()) is not None)
    raise ValueError(kind)

KINDS = ['words_min','words_max','sent_min','sent_max','paragraphs','keywords','word_freq','end_phrase','postscript','lowercase','uppercase',
         'no_commas','quotation','json','title','highlights','bullets','repeat','two_resp','placeholders','sections','start_word']
CONFLICT = {
 'json': set(KINDS)-{'json','keywords','lowercase','words_min','words_max','word_freq','no_commas'},
 'quotation': {'json','repeat','two_resp','end_phrase','start_word','postscript'},
 'lowercase': {'uppercase','sections','title','start_word'},
 'uppercase': {'lowercase','repeat','start_word','end_phrase','keywords','word_freq'},
 'words_min': {'words_max','sent_max'}, 'words_max': {'words_min','sent_min'},
 'sent_min': {'sent_max','words_max'}, 'sent_max': {'sent_min','words_min'},
 'end_phrase': {'postscript','quotation','two_resp'}, 'postscript': {'end_phrase','quotation'},
 'repeat': {'start_word','quotation','two_resp','json','uppercase'}, 'start_word': {'repeat','quotation','lowercase','uppercase'},
 'two_resp': {'json','quotation','repeat','paragraphs','sections','end_phrase'},
 'paragraphs': {'json','two_resp','sections','bullets'}, 'sections': {'json','two_resp','paragraphs','lowercase'},
 'bullets': {'json','paragraphs'},
}
def conflicts(a,b): return b in CONFLICT.get(a,set()) or a in CONFLICT.get(b,set())

