_, c = make_instruction('sections','x',random.Random(1)); print(_); t_ok.append(c("SECTION 1\nfoo\nSECTION 2\nbar") or c("SECTION 1\nfoo\nSECTION 2\nbar\nSECTION 3\nbaz") or c("SECTION 1\nfoo\nSECTION 2\nbar\nSECTION 3\nbaz\nSECTION 4\nq"))
_, c = make_instruction('two_resp','x',r0); t_ok.append(c("one\n******\ntwo")); t_ok.append(not c("one"))
_, c = make_instruction('repeat','Write a poem.',r0); t_ok.append(c("Write a poem.\n\nRoses...")); t_ok.append(not c("Sure! Write a poem."))
_, c = make_instruction('bullets','x',random.Random(2)); print(_); 
print(t_ok, len(sentences("Hi there. I am here! Are you? Yes")), len(words("It's a dog-day, 12 cats.")))

# Hypothesis: none -- programmatic 10-option MC questions with verified keys.
LET = 'ABCDEFGHIJ'
def fmt(x, nd):
    if nd == 0: return f"{int(round(x))}"
    return f"{x:.{nd}f}"
def numeric_opts(ans, r, nd=2, unit='', extra=()):
    cands = [ans*f for f in (0.5,2,1.5,0.75,1.25,0.8,1.2,0.9,1.1,3,0.25,4,0.6,1.4)] + list(extra)
    vals = []
    a_s = fmt(ans, nd)
    seen = {a_s}
    r.shuffle(cands)
    for c in list(extra) + cands:
        s = fmt(c, nd)
        if s not in seen and (abs(c) > 0 or ans==0):
            seen.add(s); vals.append(s)
        if len(vals) == 9: break
    k = 1
    while len(vals) < 9:
        s = fmt(ans + k*(10**-nd if nd>0 else 1)*r.choice([1,-1])*r.randint(1,9), nd)
        if s not in seen: seen.add(s); vals.append(s)
        k += 1
    opts = vals + [a_s]
    r.shuffle(opts)
    u = (' '+unit) if unit else ''
    return [o+u for o in opts], opts.index(a_s)

def g_kin(r):
    v0=r.randint(0,20); a=r.randint(1,9); t=r.randint(2,12)
    d=v0*t+0.5*a*t*t
    q=f"A car moving at {v0} m/s accelerates uniformly at {a} m/s^2 for {t} s. How far does it travel during this time?"
    return 'physics', q, *numeric_opts(d, r, 1, 'm', extra=(v0*t+a*t*t, a*t*t/2, v0*t))
def g_proj(r):
    v=r.choice([10,12,14,15,18,20,24,25,30]); g=9.8
    h=v*v/(2*g)
    q=f"A ball is thrown straight up with a speed of {v} m/s. Ignoring air resistance and taking g = 9.8 m/s^2, what is its maximum height?"
    return 'physics', q, *numeric_opts(h, r, 2, 'm', extra=(v*v/g, v/g))
def g_ohm(r):
    V=r.choice([6,9,12,18,24,120,230]); R=r.choice([2,3,4,5,6,8,10,12,15,20,30,47,100])
    P=V*V/R
    q=f"A resistor of {R} ohms is connected across a {V} V source. What power does it dissipate?"
    return 'physics', q, *numeric_opts(P, r, 2, 'W', extra=(V/R, V*R, V*V*R/1000))
def g_par(r):
    a,b,c=r.sample([2,3,4,5,6,8,10,12,15,20,24,30],3)
    R=1/(1/a+1/b+1/c)
    q=f"Three resistors of {a}, {b} and {c} ohms are connected in parallel. What is the equivalent resistance?"
    return 'physics', q, *numeric_opts(R, r, 2, 'ohms', extra=(a+b+c, (a+b+c)/3))
def g_ke(r):
    m=r.choice([0.5,1,2,3,4,5,10,20,50,1200]); v=r.randint(2,30)
    K=0.5*m*v*v
    q=f"What is the kinetic energy of a {m} kg object moving at {v} m/s?"
    return 'physics', q, *numeric_opts(K, r, 1, 'J', extra=(m*v*v, m*v))
def g_mom(r):
    m1=r.randint(1,10); v1=r.randint(1,15); m2=r.randint(1,10)
    v=m1*v1/(m1+m2)
    q=f"A {m1} kg cart moving at {v1} m/s collides with and sticks to a stationary {m2} kg cart. What is their common speed after the collision?"
    return 'physics', q, *numeric_opts(v, r, 2, 'm/s', extra=(m1*v1/m2, v1/2))
def g_wave(r):
    f=r.choice([50,100,200,256,440,500,1000]); lam=r.choice([0.5,0.68,0.75,1.2,1.5,2,3.4])
    q=f"A wave has frequency {f} Hz and wavelength {lam} m. What is its speed?"
    return 'physics', q, *numeric_opts(f*lam, r, 1, 'm/s', extra=(f/lam, lam/f))
def g_heat(r):
    m=r.choice([0.2,0.5,1,1.5,2,3]); dT=r.randint(5,60); c=r.choice([(4186,'water'),(900,'aluminum'),(385,'copper'),(450,'iron')])
    Q=m*c[0]*dT
    q=f"How much heat is needed to raise the temperature of {m} kg of {c[1]} by {dT} degrees Celsius? (specific heat {c[0]} J/(kg K))"
    return 'engineering', q, *numeric_opts(Q, r, 0, 'J', extra=(m*c[0], c[0]*dT))
def g_molar(r):
    comps={'H2O':18.015,'CO2':44.009,'NaCl':58.44,'CaCO3':100.086,'C6H12O6':180.156,'H2SO4':98.079,'NH3':17.031,'CH4':16.043,'KCl':74.551,'MgO':40.304,'NaOH':39.997,'HCl':36.458}
    k=r.choice(list(comps)); m=r.choice([5,10,18,25,36,50,72,100,150,200])
    n=m/comps[k]
    q=f"How many moles are there in {m} g of {k}? (Use standard atomic masses.)"
    return 'chemistry', q, *numeric_opts(n, r, 3, 'mol', extra=(m*comps[k]/1000, comps[k]/m))
def g_gas(r):
    n=r.choice([0.5,1,1.5,2,2.5,3]); T=r.choice([273,298,300,350,400]); V=r.choice([5,10,15,20,22.4,25])
    P=n*0.08206*T/V
    q=f"What is the pressure of {n} mol of an ideal gas at {T} K in a {V} L container? (R = 0.08206 L atm / (mol K))"
    return 'chemistry', q, *numeric_opts(P, r, 2, 'atm', extra=(n*8.314*T/V/100, n*T/V))
def g_dil(r):
    C1=r.choice([0.5,1,2,3,6,12]); V1=r.choice([10,20,25,50,100]); V2=r.choice([200,250,500,1000])
    C2=C1*V1/V2
    q=f"{V1} mL of a {C1} M solution is diluted to a final volume of {V2} mL. What is the new concentration?"
    return 'chemistry', q, *numeric_opts(C2, r, 3, 'M', extra=(C1*V2/V1/100, C1*V1/(V1+V2)))
def g_ph(r):
    e=r.randint(1,6); c=r.choice([1,2,5])
    import math
    pH=-math.log10(c*10**(-e))
    q=f"What is the pH of a {c}x10^-{e} M solution of a strong monoprotic acid?"
    return 'chemistry', q, *numeric_opts(pH, r, 2, '', extra=(e, 14-pH, pH+1))
def g_cint(r):
    P=r.choice([1000,2000,2500,5000,10000]); rate=r.choice([2,3,4,5,6,7,8]); t=r.randint(2,15)
    A=P*(1+rate/100)**t
    q=f"An investment of ${P} earns {rate}% interest per year, compounded annually. What is it worth after {t} years?"
    return 'economics', q, *numeric_opts(A, r, 2, '', extra=(P*(1+rate*t/100), P*rate*t/100))
def g_pct(r):
    a=r.randint(20,500); b=a+r.choice([-1,1])*r.randint(5,a-5)
    p=(b-a)/a*100
    q=f"The price of a good changes from ${a} to ${b}. What is the percentage change in price?"
    return 'economics', q, *numeric_opts(p, r, 2, '%', extra=((b-a)/b*100, -p))
def g_be(r):
    F=r.choice([1000,2400,5000,12000,30000]); p=r.randint(15,80); vc=r.randint(5,p-5)
    n=F/(p-vc)
    q=f"A firm has fixed costs of ${F}. Each unit sells for ${p} and has a variable cost of ${vc}. How many units must it sell to break even?"
    return 'economics', q, *numeric_opts(n, r, 1, 'units', extra=(F/p, F/vc))
def g_elas(r):
    p1=r.randint(5,20); p2=p1+r.randint(1,5); q1=r.randint(100,400); q2=q1-r.randint(10,90)
    e=((q2-q1)/((q1+q2)/2))/((p2-p1)/((p1+p2)/2))
    q=f"When the price rises from ${p1} to ${p2}, the quantity demanded falls from {q1} to {q2}. Using the midpoint method, what is the price elasticity of demand?"
    return 'economics', q, *numeric_opts(e, r, 2, '', extra=(-e, ((q2-q1)/q1)/((p2-p1)/p1)))
def g_prob(r):
    a=r.randint(2,6); b=r.randint(2,6); k=r.randint(1,min(a,3))
    from math import comb
    p=comb(a,k)*comb(b,3-k)/comb(a+b,3) if 3-k<=b else 0
    q=f"A bag has {a} red and {b} blue marbles. Three are drawn without replacement. What is the probability that exactly {k} are red?"
    return 'math', q, *numeric_opts(p, r, 3, '', extra=(comb(3,k)*(a/(a+b))**k*(b/(a+b))**(3-k),))
def g_comb(r):
    n=r.randint(6,14); k=r.randint(2,5)
    from math import comb, perm
    q=f"In how many ways can a committee of {k} people be chosen from {n} people?"
    return 'math', q, *numeric_opts(comb(n,k), r, 0, '', extra=(perm(n,k), n**k, comb(n,k-1)))
def g_bin(r):
    x=r.randint(37,1000)
    q=f"What is the decimal value of the binary number {bin(x)[2:]}?"
    return 'computer science', q, *numeric_opts(x, r, 0, '', extra=(x+1, x-1, x*2, x//2, int(bin(x)[2:][::-1],2)))
def g_hex(r):
    x=r.randint(256,65535)
    q=f"What is the decimal value of the hexadecimal number {hex(x)[2:].upper()}?"
    return 'computer science', q, *numeric_opts(x, r, 0, '', extra=(x+16, x-16, x+256, x-1))
def g_edges(r):
    n=r.randint(5,40)
    q=f"How many edges does a complete undirected graph with {n} vertices have?"
    return 'computer science', q, *numeric_opts(n*(n-1)//2, r, 0, '', extra=(n*(n-1), n*n, n-1, n*(n+1)//2))
def g_hw(r):
    qq=r.choice([0.1,0.2,0.3,0.4,0.6,0.7])
    q=f"In a population in Hardy-Weinberg equilibrium, the frequency of a recessive allele is {qq}. What fraction of the population is heterozygous?"
    return 'biology', q, *numeric_opts(2*qq*(1-qq), r, 2, '', extra=(qq*qq, (1-qq)**2, qq*(1-qq)))
def g_cross(r):
    q=r.choice([("Aa x Aa","show the recessive phenotype",0.25),("Aa x aa","show the recessive phenotype",0.5),("AaBb x AaBb","show both recessive phenotypes",1/16),
                ("AaBb x AaBb","show both dominant phenotypes",9/16),("AaBb x aabb","show both recessive phenotypes",0.25),("Aa x Aa","be heterozygous",0.5)])
    qs=f"In a cross {q[0]} with simple dominance and independent assortment, what fraction of offspring will {q[1]}?"
    return 'biology', qs, *numeric_opts(q[2], r, 4, '', extra=(0.75, 0.5, 0.25, 1/16, 3/16, 9/16, 0.125))
def g_conv(r):
    c=r.choice([("miles","kilometers",1.609344),("pounds","kilograms",0.45359237),("inches","centimeters",2.54),("gallons (US)","liters",3.785411784),("feet","meters",0.3048)])
    x=r.randint(3,250)
    q=f"Convert {x} {c[0]} to {c[1]}."
    return 'engineering', q, *numeric_opts(x*c[2], r, 2, c[1], extra=(x/c[2],))
def g_mean(r):
    xs=[r.randint(1,60) for _ in range(r.randint(5,9))]
    import statistics
    q=f"What is the median of the data set {', '.join(map(str,xs))}?"
    return 'math', q, *numeric_opts(statistics.median(xs), r, 1, '', extra=(statistics.mean(xs), sorted(xs)[len(xs)//2-1], xs[len(xs)//2]))
